Clase Producto
    Privado Definir precio Como Entero;

    Metodo Constructor(unPrecio Como Entero)
        Este.precio <- unPrecio;
    FinMetodo

    Publico Metodo Precio() Como Entero
        Retornar Este.precio;
    FinMetodo
FinClase

Clase Factura
    Privado Definir producto1 Como Producto;
    Privado Definir producto2 Como Producto;

    Metodo Constructor(unPrecio1 Como Entero, unPrecio2 Como Entero)
        Este.producto1 <- Nuevo Producto(unPrecio1);
        Este.producto2 <- Nuevo Producto(unPrecio2);
    FinMetodo

    Publico Metodo Total() Como Entero
        Retornar Este.producto1.Precio() + Este.producto2.Precio();
    FinMetodo
FinClase

Proceso CalcularFactura
    Definir p1 Como Entero;
    Definir p2 Como Entero;
    Definir factura Como Factura;
    Leer p1;
    Leer p2;
    factura <- Nuevo Factura(p1, p2);
    Escribir factura.Total();
FinProceso
